extends CanvasLayer
class_name TopDialogueOverlay

## Non-blocking top-of-screen line; does not pause physics or capture input.

const FADE_IN_SEC := 0.22
const FADE_OUT_SEC := 0.22

@onready var _root_margin: MarginContainer = $RootMargin
@onready var _bar: PanelContainer = $RootMargin/BarPanel
@onready var _label: Label = $RootMargin/BarPanel/LineLabel


func _ready() -> void:
	layer = 110
	visible = false
	modulate.a = 0.0
	_set_ignore_mouse_recursive(self)


func _set_ignore_mouse_recursive(n: Node) -> void:
	if n is Control:
		(n as Control).mouse_filter = Control.MOUSE_FILTER_IGNORE
	for c in n.get_children():
		_set_ignore_mouse_recursive(c)


## Fade in, hold, fade out. Safe to await; does not disable player movement.
func show_line(text: String, hold_duration: float = 2.5) -> void:
	_label.text = text
	visible = true
	var tw_in := create_tween()
	tw_in.tween_property(self, "modulate:a", 1.0, FADE_IN_SEC)
	await tw_in.finished
	await get_tree().create_timer(maxf(hold_duration, 0.05)).timeout
	await hide_line()


func hide_line() -> void:
	if not visible:
		return
	var tw_out := create_tween()
	tw_out.tween_property(self, "modulate:a", 0.0, FADE_OUT_SEC)
	await tw_out.finished
	visible = false

extends Node2D

@onready var _top_dialogue: TopDialogueOverlay = $TopDialogueOverlay


func _ready() -> void:
	_run_intro_dialogue()


func _run_intro_dialogue() -> void:
	await _top_dialogue.show_line("You promised, you'd never come back.", 2.0)
	await get_tree().create_timer(0.8).timeout
	await _top_dialogue.show_line("Yet, here we are.", 2.5)

